const input = $input.first();
const body = input.json && typeof input.json.body === 'object' && input.json.body !== null ? input.json.body : input.json;
const requiredText = (name, maximum) => {
  const value = body[name];
  if (typeof value !== 'string' || value.trim() !== value || value.length < 1 || value.length > maximum) throw new Error(`IMPORT_INVALID_${name.toUpperCase()}`);
  return value;
};
const submissionId = requiredText('submission_id', 64);
const idempotencyKey = requiredText('idempotency_key', 128);
const fileSha256 = requiredText('file_sha256', 64);
const contractVersion = requiredText('contract_version', 64);
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(submissionId)) throw new Error('IMPORT_INVALID_SUBMISSION_ID');
if (!/^[0-9a-f]{64}$/.test(fileSha256)) throw new Error('IMPORT_INVALID_FILE_HASH');
if (contractVersion !== 'prospecta-import-v1') throw new Error('IMPORT_UNSUPPORTED_CONTRACT');
const binary = input.binary || {};
const binaryPropertyName = binary.arquivo_csv ? 'arquivo_csv' : null;
if (binaryPropertyName === null) throw new Error('IMPORT_FILE_REQUIRED');
const file = binary[binaryPropertyName];
const bytes = await this.helpers.getBinaryDataBuffer(0, binaryPropertyName);
if (bytes.byteLength < 1 || bytes.byteLength > 10485760) throw new Error('IMPORT_FILE_SIZE_INVALID');
if (!/\.csv$/i.test(String(file.fileName || ''))) throw new Error('IMPORT_FILE_TYPE_INVALID');
if (!['text/csv', 'application/csv', 'application/vnd.ms-excel'].includes(String(file.mimeType || '').toLowerCase())) throw new Error('IMPORT_FILE_TYPE_INVALID');
let decoded;
try { decoded = new TextDecoder('utf-8', { fatal: true }).decode(bytes); } catch { throw new Error('IMPORT_FILE_ENCODING_INVALID'); }
if (!decoded.replace(/^\uFEFF/, '').trim()) throw new Error('IMPORT_FILE_EMPTY');
const digest = await globalThis.crypto.subtle.digest('SHA-256', bytes);
const computedSha256 = [...new Uint8Array(digest)].map((value) => value.toString(16).padStart(2, '0')).join('');
if (computedSha256 !== fileSha256) throw new Error('IMPORT_FILE_HASH_MISMATCH');
return [{
  json: {
    submission_id: submissionId,
    idempotency_key: idempotencyKey,
    file_sha256: fileSha256,
    contract_version: contractVersion,
    binary_property_name: binaryPropertyName,
    original_filename: String(file.fileName || ''),
    file_size_bytes: bytes.byteLength,
    file_mime_type: String(file.mimeType || '')
  },
  binary: input.binary
}];

const items = $input.all();
if (items.length < 1) throw new Error('IMPORT_ROWS_REQUIRED');
const canonical = (value) => String(value ?? '').replace(/^\uFEFF/, '').replace(/\u00A0/g, ' ').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
const cleanObject = (value) => Object.fromEntries(Object.entries(value || {}).map(([key, field]) => [String(key).replace(/^\uFEFF/, '').replace(/\u00A0/g, ' ').trim(), field]));
const aliases = {
  cnpj: ['cnpj', 'documento', 'tax_id'],
  razao: ['razao', 'razao_social', 'razao social', 'nome_empresarial', 'company_name'],
  fantasia: ['fantasia', 'nome_fantasia', 'nome fantasia', 'trade_name'],
  cidade: ['cidade', 'municipio', 'city'],
  uf: ['uf', 'estado', 'state'],
  site: ['site', 'website', 'site_url', 'homepage'],
  email: ['e_mail', 'e-mail', 'email', 'mail'],
  telefone: ['telefone_1', 'telefone', 'phone', 'fone', 'celular']
};
const hasField = (row, names) => {
  const wanted = new Set(names.map(canonical));
  return Object.keys(row).some((key) => wanted.has(canonical(key)));
};
const field = (row, names) => {
  const wanted = new Set(names.map(canonical));
  const match = Object.entries(row).find(([key]) => wanted.has(canonical(key)));
  return match ? String(match[1] ?? '').trim() : '';
};
const first = cleanObject(items[0].json.row ?? items[0].json);
if (!hasField(first, aliases.cnpj) || !hasField(first, aliases.razao)) throw new Error('IMPORT_REQUIRED_HEADERS_MISSING');
const stable = (value) => value === null || value === undefined ? 'null' : (Array.isArray(value) ? `[${value.map(stable).join(',')}]` : (typeof value === 'object' ? `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stable(value[key])}`).join(',')}}` : JSON.stringify(value)));
const sha256 = async (value) => {
  const digest = await globalThis.crypto.subtle.digest('SHA-256', new TextEncoder().encode(value));
  return [...new Uint8Array(digest)].map((part) => part.toString(16).padStart(2, '0')).join('');
};
const output = [];
for (let index = 0; index < items.length; index += 1) {
  const rawRow = cleanObject(items[index].json.row ?? items[index].json);
  const cnpj = field(rawRow, aliases.cnpj).replace(/\D/g, '');
  const normalizedPayload = {
    company: {
      cnpj: cnpj || null,
      razaoSocial: field(rawRow, aliases.razao) || null,
      nomeFantasia: field(rawRow, aliases.fantasia) || null,
      cidade: field(rawRow, aliases.cidade) || null,
      uf: field(rawRow, aliases.uf).toUpperCase() || null,
      site: field(rawRow, aliases.site) || null
    },
    contact: {
      email: field(rawRow, aliases.email) || null,
      telefone: field(rawRow, aliases.telefone) || null
    }
  };
  output.push({ json: {
    source_row: index + 2,
    cnpj_normalizado: cnpj || null,
    raw_row: rawRow,
    normalized_payload: normalizedPayload,
    raw_row_sha256: await sha256(stable(rawRow)),
    normalized_row_sha256: await sha256(stable(normalizedPayload))
  }});
}
return output;

const transport = $('Validate Transport and Hash').first().json;
const rows = $input.all().map((item) => item.json);
if (rows.length < 1 || new Set(rows.map((row) => row.source_row)).size !== rows.length) throw new Error('IMPORT_ROW_SET_INVALID');
const stable = (value) => value === null || value === undefined ? 'null' : (Array.isArray(value) ? `[${value.map(stable).join(',')}]` : (typeof value === 'object' ? `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stable(value[key])}`).join(',')}}` : JSON.stringify(value)));
const sha256 = async (value) => {
  const digest = await globalThis.crypto.subtle.digest('SHA-256', new TextEncoder().encode(value));
  return [...new Uint8Array(digest)].map((part) => part.toString(16).padStart(2, '0')).join('');
};
const headerNames = Object.keys(rows[0].raw_row).sort();
return [{ json: { acceptance_payload: {
  submission_id: transport.submission_id,
  idempotency_key: transport.idempotency_key,
  file_sha256: transport.file_sha256,
  contract_version: transport.contract_version,
  workflow_version: 'prospecta-import-v1-n8n-artifact-1',
  ruleset_version: 'empresaqui-normalization-v1',
  prompt_model_version: 'producer-worker-interface-v1',
  execution_mode: 'STANDARD',
  raw_rows_sha256: await sha256(stable(rows.map((row) => row.raw_row))),
  header_sha256: await sha256(stable(headerNames)),
  import_manifest: {
    original_filename: transport.original_filename,
    file_size_bytes: transport.file_size_bytes,
    file_mime_type: transport.file_mime_type,
    delimiter: ';',
    encoding: 'utf8',
    row_count: rows.length
  },
  rows
}}}];

let acceptance = $input.first().json.acceptance;
if (typeof acceptance === 'string') {
  try { acceptance = JSON.parse(acceptance); } catch { throw new Error('IMPORT_ACCEPTANCE_INVALID'); }
}
if (!acceptance || acceptance.accepted !== true || !/^ib_[0-9a-f]{64}$/.test(String(acceptance.import_batch_id || '')) || !Number.isSafeInteger(Number(acceptance.row_count)) || Number(acceptance.row_count) < 1 || Number.isNaN(new Date(acceptance.accepted_at).getTime())) throw new Error('IMPORT_ACCEPTANCE_INVALID');
return [{ json: {
  accepted: true,
  import_batch_id: acceptance.import_batch_id,
  message: 'Lote aceito para processamento.',
  row_count: Number(acceptance.row_count),
  source: 'EmpresaAqui'
}}];

const acceptance = $('Prepare Durable Acceptance Response').first().json;
const results = $input.all().map((item) => item.json);
const exactFields = ['worker_contract_version', 'import_batch_id', 'source_row', 'input_row_id', 'lead_run_id', 'idempotency_key', 'terminal_class'].sort();
if (results.length !== acceptance.row_count || results.length < 1) throw new Error('WORKER_TERMINAL_SET_INCOMPLETE');
const sourceRows = new Set();
for (const result of results) {
  const fields = Object.keys(result).sort();
  if (fields.length !== exactFields.length || fields.some((field, index) => field !== exactFields[index])) throw new Error('WORKER_CONTRACT_FIELDS_INVALID');
  if (result.worker_contract_version !== 'prospecta-producer-worker-v1' || result.import_batch_id !== acceptance.import_batch_id) throw new Error('WORKER_CONTRACT_IDENTITY_MISMATCH');
  if (!Number.isSafeInteger(result.source_row) || result.source_row < 2 || sourceRows.has(result.source_row)) throw new Error('WORKER_SOURCE_ROW_INVALID');
  if (![result.input_row_id, result.lead_run_id, result.idempotency_key].every((value) => typeof value === 'string' && value.length > 0 && value.length <= 160)) throw new Error('WORKER_ROW_IDENTITY_INVALID');
  if (!['MATERIALIZED', 'BLOCKED', 'FAILED'].includes(result.terminal_class)) throw new Error('WORKER_TERMINAL_CLASS_INVALID');
  sourceRows.add(result.source_row);
}
return [{ json: {
  worker_contract_version: 'prospecta-producer-worker-v1',
  import_batch_id: acceptance.import_batch_id,
  terminal_count: results.length
}}];
